use serde::{Deserialize, Serialize};
use std::collections::HashMap;

# [doc = " Used to create a new [`ThreadPool`] or to configure the global rayon thread pool."] # [doc = " ## Creating a ThreadPool"] # [doc = " The following creates a thread pool with 22 threads."] # [doc = ""] # [doc = " ```ignore-wasm"] # [doc = " # use rayon_core as rayon;"] # [doc = " let pool = rayon::ThreadPoolBuilder::new().num_threads(22).build().unwrap();"] # [doc = " ```"] # [doc = ""] # [doc = " To instead configure the global thread pool, use [`build_global()`]:"] # [doc = ""] # [doc = " ```ignore-wasm"] # [doc = " # use rayon_core as rayon;"] # [doc = " rayon::ThreadPoolBuilder::new().num_threads(22).build_global().unwrap();"] # [doc = " ```"] # [doc = ""] # [doc = " [`build_global()`]: Self::build_global()"] pub struct ThreadPoolBuilder < S = DefaultSpawn > { # [doc = " The number of threads in the rayon thread pool."] # [doc = " If zero will use the RAYON_NUM_THREADS environment variable."] # [doc = " If RAYON_NUM_THREADS is invalid or zero will use the default."] num_threads : usize , # [doc = " The thread we're building *from* will also be part of the pool."] use_current_thread : bool , # [doc = " Custom closure, if any, to handle a panic that we cannot propagate"] # [doc = " anywhere else."] panic_handler : Option < Box < PanicHandler > > , # [doc = " Closure to compute the name of a thread."] get_thread_name : Option < Box < dyn FnMut (usize) -> String > > , # [doc = " The stack size for the created worker threads"] stack_size : Option < usize > , # [doc = " Closure invoked on worker-thread start."] start_handler : Option < Box < StartHandler > > , # [doc = " Closure invoked on worker-thread exit."] exit_handler : Option < Box < ExitHandler > > , # [doc = " Closure invoked to spawn threads."] spawn_handler : S , # [doc = " If false, worker threads will execute spawned jobs in a"] # [doc = " \"depth-first\" fashion. If true, they will do a \"breadth-first\""] # [doc = " fashion. Depth-first is the default."] breadth_first : bool , }